{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 경제적 부담으로 건강지원을 못 받는 청년 우선 지원 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제18조제1항에 따르면 시장은 청년의 신체적·정신적 건강을 보호·증진하기 위한 방안을 강구하여야 하며 예산의 범위에서 지원을 할 수 있고, 이 경우 사회·경제적 이유 등으로 건강관리에 어려움을 겪는 청년을 우선적으로 고려하여야 한다. 따라서 경제적 부담 때문에 건강지원을 받지 못하는 청년은 우선 고려 대상에 해당한다. 다만 실제 지원 여부와 지원 내용은 예산의 범위 등 구체적 기준에 따라 정해진다.",
          "b_ids": "청년:제18조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 청년 기본 조례상 서울청년센터에서 상담 관련 지원·안내를 받을 수 있는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제20조제3항제1호는 자치구별 서울청년센터의 기능으로 청년지원정보 집적·제공 및 분야별 종합상담 사업을 규정하고 있다. 또한 같은 항 제3호는 청년의 심리적 안정 및 자립지원, 취약계층 청년 지원 등 사회안전망 사업을 서울청년센터의 기능으로 정하고 있다. 따라서 청년센터에서 상담 관련 지원이나 안내를 알아보는 것은 조례상 서울청년센터의 기능 범위에 포함된다.",
          "b_ids": "청년:제20조제3항제1호, 청년:제20조제3항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
